import fs from 'fs';
import path from 'path';

const logDir = 'C:\\Users\\nttis\\.gemini\\antigravity-ide\\brain\\42bc13d7-a338-402f-b102-db6130b68266\\.system_generated\\logs';
const transcriptPath = path.join(logDir, 'transcript_full.jsonl');
const rawAuditPath = 'c:\\Users\\nttis\\Downloads\\SUT_HW04\\RAW_AUDIT_LOG.json';
const artifactRawPath = 'C:\\Users\\nttis\\.gemini\\antigravity-ide\\brain\\42bc13d7-a338-402f-b102-db6130b68266\\RAW_AUDIT_LOG.json';
const mdAuditPath = 'c:\\Users\\nttis\\Downloads\\SUT_HW04\\AI_AUDIT_LOG.md';
const artifactMdPath = 'C:\\Users\\nttis\\.gemini\\antigravity-ide\\brain\\42bc13d7-a338-402f-b102-db6130b68266\\AI_AUDIT_LOG.md';

const lines = fs.readFileSync(transcriptPath, 'utf8').split('\n').filter(Boolean);

const rawEntries = [];
const mdTurns = [];

let currentTurn = null;
let turnCount = 0;

for (const line of lines) {
  let entry;
  try {
    entry = JSON.parse(line);
  } catch (e) {
    continue;
  }

  rawEntries.push(entry);

  if (entry.type === 'USER_INPUT') {
    turnCount++;
    currentTurn = {
      turn: turnCount,
      timestamp: entry.created_at,
      user_prompt: entry.content || '',
      thinking_blocks: [],
      model_responses: [],
      tool_calls: []
    };
    mdTurns.push(currentTurn);
  } else if (currentTurn) {
    if (entry.thinking) {
      currentTurn.thinking_blocks.push(entry.thinking);
    }
    if (entry.content && entry.type === 'PLANNER_RESPONSE') {
      currentTurn.model_responses.push(entry.content);
    }
    if (entry.tool_calls && entry.tool_calls.length > 0) {
      for (const tc of entry.tool_calls) {
        currentTurn.tool_calls.push({
          tool: tc.name,
          args: tc.args
        });
      }
    }
  }
}

// Write full raw audit JSON
fs.writeFileSync(rawAuditPath, JSON.stringify(rawEntries, null, 2), 'utf8');
fs.writeFileSync(artifactRawPath, JSON.stringify(rawEntries, null, 2), 'utf8');

console.log(`Parsed ${rawEntries.length} raw log entries into RAW_AUDIT_LOG.json (${(fs.statSync(rawAuditPath).size / 1024 / 1024).toFixed(2)} MB).`);

// Build comprehensive markdown audit log
