---

## Complete Turn-by-Turn Trajectory Audit

`;

for (const t of mdTurns) {
  mdContent += `### Turn ${t.turn} (${t.timestamp || 'N/A'})\n\n`;

  // Clean user prompt display
  let cleanPrompt = t.user_prompt
    .replace(/<ADDITIONAL_METADATA>[\s\S]*?<\/ADDITIONAL_METADATA>/g, '')
    .replace(/<USER_SETTINGS_CHANGE>[\s\S]*?<\/USER_SETTINGS_CHANGE>/g, '')
    .trim();

  mdContent += `#### 👤 User Prompt\n\`\`\`text\n${cleanPrompt || t.user_prompt}\n\`\`\`\n\n`;

  if (t.thinking_blocks.length > 0) {
    mdContent += `#### 🧠 AI Internal Reasoning (Thinking)\n`;
    for (let i = 0; i < t.thinking_blocks.length; i++) {
      mdContent += `> [!NOTE]\n> **Thinking Block ${i+1}:**\n> ${t.thinking_blocks[i].replace(/\n/g, '\n> ')}\n\n`;
    }
  }

  if (t.tool_calls.length > 0) {
    mdContent += `#### 🛠️ Tool Invocations (${t.tool_calls.length} call${t.tool_calls.length > 1 ? 's' : ''})\n`;
    for (const tc of t.tool_calls) {
      let argsStr = typeof tc.args === 'string' ? tc.args : JSON.stringify(tc.args, null, 2);
      if (argsStr.length > 300) argsStr = argsStr.substring(0, 300) + '... (truncated for readability)';
      mdContent += `- **Tool:** \`${tc.tool}\` | **Args:** \`${argsStr}\` \n`;
    }
    mdContent += `\n`;
  }

  if (t.model_responses.length > 0) {
    mdContent += `#### 🤖 AI Assistant Response\n\n${t.model_responses.join('\n\n')}\n\n`;
  }

  mdContent += `---\n\n`;
}

fs.writeFileSync(mdAuditPath, mdContent, 'utf8');
